const $=id=>document.getElementById(id),icon=name=>`<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const audio=createAudioEngine($('audio'),{notify:text=>toast(text)});
const state={tracks:[],current:null,filter:'all',query:'',sort:'featured',client:null,profile:null,owner:false,comments:[],commentTrack:null,reply:null,editComment:null,loading:true,communityError:'',view:'inicio'};
const router=createRouter({onChange:route});
function read(key, fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function store(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{}}
const saved=read('kyroshix-favorites',[]), favorites=new Set(Array.isArray(saved)?saved.filter(x=>typeof x==='string'):[]);
let musicPlayer=null,listeningRoom=null;
let listView=read('kyroshix-view','grid')==='list',queue=[],shuffled=false,playAttempt=0,toastTimer,routeEpoch=0,commentEpoch=0,identityEpoch=0,profileDraft=null,profileBlobs={},trackDraft=null,trackBlob=null,editImageUrl='',profileBusy=false,trackBusy=false,commentBusy=false;
audio.volume=Math.min(1,Math.max(0,Number(read('kyroshix-volume',.8))||0));$('volume').value=audio.volume;
function toast(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').classList.add('visible');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4500);}
function message(id,text='',kind=''){const el=$(id);el.textContent=text;el.hidden=!text;el.dataset.error=String(kind==='error');el.dataset.success=String(kind==='success');el.setAttribute('role',kind==='error'?'alert':'status');}
function media(path,version=''){if(!path)return '';if(/^assets\/(remember|legends|darkness|blindfold)\.mp3$/.test(path))return '/'+path;return state.client?.media(path,version)||'';}
function cover(t,extra=''){const url=media(t.cover_path);return `<div class="cover-art ${legacyCover(t.legacy_cover)} ${extra}" ${url?`style="background-image:url('${esc(url)}');background-size:cover;background-position:center"`:''}></div>`;}
function paintCover(el,t){el.className=`${el.dataset.baseClass||'mini-cover'} ${legacyCover(t?.legacy_cover)}`;el.style.backgroundImage=t?.cover_path?`url("${media(t.cover_path)}")`:'';el.style.backgroundSize=t?.cover_path?'cover':'';el.style.backgroundPosition=t?.cover_path?'center':'';}
function avatar(profile,cls='avatar'){const url=media(profile?.avatar_path,profile?.updated_at);return `<span data-initial="${esc(Array.from(profile?.display_name||'O')[0].toUpperCase())}" class="${cls} ${url?'has-image':''}" style="background-color:${accent(profile?.accent)}">${url?`<img src="${esc(url)}" alt="" loading="lazy">`:esc(Array.from(profile?.display_name||'O')[0].toUpperCase())}</span>`;}
function byId(id){return state.tracks.find(t=>t.id===id);}
function selectedTracks(){return filterTracks(state.view==='recentes'?(listeningRoom?.recent()||[]):state.tracks,{...state,sort:state.view==='recentes'?'featured':state.sort,favoritesOnly:state.view==='favoritas',favorites});}
function downloadUrl(t){const url=media(t.audio_path);return url.startsWith('https:')?url+'?download='+encodeURIComponent(downloadName(t)):url;}
function setDownload(el,t){if(!t){el.removeAttribute('href');return;}el.href=downloadUrl(t);el.download=downloadName(t);el.setAttribute('aria-label',`Baixar ${t.title} em ${audioExtension(t).toUpperCase()}`);}
function card(t){return `<article class="release-card ${state.current?.id===t.id?'selected':''}" data-track="${esc(t.id)}"><div class="card-cover"><a href="${esc(trackPath(t))}" aria-label="Abrir ${esc(t.title)}">${cover(t)}</a><button class="card-play" data-play="${esc(t.id)}" aria-label="Reproduzir ${esc(t.title)}">${icon(state.current?.id===t.id&&!audio.paused?'pause':'play')}</button><span class="card-duration">${format(t.duration)}</span></div><div class="track-information"><div class="track-heading"><h3><a href="${esc(trackPath(t))}">${esc(t.title)}</a></h3><button class="icon-button ${favorites.has(t.id)?'active':''}" data-favorite="${esc(t.id)}" aria-pressed="${favorites.has(t.id)}" aria-label="Favoritar ${esc(t.title)}">${icon('heart')}</button></div><p class="track-artists">${esc(t.artists)}</p><div class="track-bottom"><span class="track-remix">${esc(t.remix)}</span><a class="card-download" href="${esc(downloadUrl(t))}" download="${esc(downloadName(t))}">${icon('download')}Baixar áudio</a></div></div></article>`;}
function drawCatalog(){
 $('welcome').hidden=state.view!=='inicio'||!!state.query;document.body.classList.toggle('home-route',!$('welcome').hidden);
 const rows=selectedTracks();$('release-grid').innerHTML=rows.map(card).join('');$('release-grid').classList.toggle('list-view',listView);
 $('empty-state').hidden=!!rows.length||state.loading||!!state.communityError;$('empty-description').textContent=state.view==='recentes'?'As músicas que você ouvir aparecerão aqui. O histórico fica neste navegador.':state.view==='favoritas'?'Suas favoritas ficam salvas neste navegador. Toque no coração de uma faixa.':'Experimente outro título, artista ou estilo.';
 $('catalog-heading').textContent=state.view==='recentes'?'Ouvidas recentemente':state.view==='favoritas'?'Favoritas':state.query?'Resultados da busca':state.view==='musicas'?'Músicas':'Descobrir';
 $('release-heading').textContent=state.view==='recentes'?'Seu histórico':state.view==='favoritas'?'Sua seleção':state.query?`Resultados para “${state.query}”`:'Todos os lançamentos';
 $('catalog-total').textContent=`${state.tracks.length} faixas`;$('nav-count').textContent=state.tracks.length;$('favorites-count').textContent=state.tracks.filter(t=>favorites.has(t.id)).length;
 const seconds=rows.reduce((sum,t)=>sum+Number(t.duration),0);$('collection-count').textContent=`${rows.length} ${rows.length===1?'faixa':'faixas'} · ${Math.floor(seconds/60)} min`;
 $('sort').hidden=state.view==='recentes';$('discovery-shuffle').hidden=state.view==='recentes';$('discovery-shuffle').disabled=!rows.length;$('play-all').disabled=!rows.length;$('clear-search').hidden=!state.query;
 $('view-toggle').innerHTML=icon(listView?'grid':'list');$('view-toggle').setAttribute('aria-label',`Alternar para ${listView?'grade':'lista'}`);
 document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===state.filter);b.setAttribute('aria-pressed',String(b.dataset.filter===state.filter));});
 const feature=state.tracks.find(t=>t.featured)||state.tracks[0];$('spotlight').hidden=!feature||state.view!=='inicio'||!!state.query||state.filter!=='all';
 if(feature){$('spotlight').innerHTML=`<a class="spotlight-art" href="${esc(trackPath(feature))}" aria-label="Abrir ${esc(feature.title)}">${cover(feature)}</a><div class="spotlight-copy"><span class="eyebrow">EM DESTAQUE · ${esc(feature.remix)}</span><h2>${esc(feature.title)}</h2><p>${esc(feature.artists)}</p><p class="spotlight-description">${esc(feature.description?.slice(0,130)||'Remix por KYROSHIX.')}</p><div class="spotlight-actions"><button class="primary" data-play="${esc(feature.id)}">${icon('play')}Ouvir agora</button><a class="secondary" href="${esc(trackPath(feature))}">Explorar faixa</a><span class="pill">${audioExtension(feature).toUpperCase()}</span></div></div>`;}
 listeningRoom?.renderSections();listeningRoom?.sync();
 if(state.loading)message('catalog-message','Carregando músicas…');else message('catalog-message',state.communityError,state.communityError?'error':'');
}
function syncPlayback(){const t=state.current,playing=!!t&&!audio.paused;document.body.classList.toggle('audio-playing',playing);if(playing)document.body.classList.add('audio-started');$('play-toggle').innerHTML=icon(playing?'pause':'play');$('play-toggle').disabled=!t;$('play-toggle').setAttribute('aria-label',`${playing?'Pausar':'Reproduzir'} ${t?.title||''}`);$('favorite').disabled=!t;$('favorite').setAttribute('aria-pressed',String(!!t&&favorites.has(t.id)));$('favorite').classList.toggle('active',!!t&&favorites.has(t.id));document.querySelectorAll('[data-play]').forEach(b=>{const active=b.dataset.play===t?.id;b.closest('.release-card')?.classList.toggle('selected',active);if(b.classList.contains('card-play')||b.classList.contains('detail-play'))b.innerHTML=icon(active&&playing?'pause':'play');});musicPlayer?.sync();listeningRoom?.sync();if('mediaSession'in navigator)navigator.mediaSession.playbackState=playing?'playing':'paused';}
async function play(){if(!state.current)return;const attempt=++playAttempt;try{if(audio.error)audio.load();await audio.play();}catch(e){if(e.name!=='AbortError'&&attempt===playAttempt)toast('Não foi possível tocar. Confira a conexão e tente novamente.');}syncPlayback();}
function showTrack(t){if(!t)return;state.current=t;plannedNext=null;autoAttempted='';$('player-title').textContent=t.title;$('player-artist').textContent=t.artists;paintCover($('player-cover'),t);setDownload($('player-download'),t);updateProgress();syncPlayback();if('mediaSession'in navigator&&'MediaMetadata'in window)navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artists,album:'KYROSHIX RELEASES'});}
async function loadTrack(t,autoplay=true){if(!t)return;const attempt=++playAttempt;try{await audio.select(media(t.audio_path),{autoplay,fade:autoplay,item:t});}catch(error){if(error.name!=='AbortError'&&attempt===playAttempt)toast('Não foi possível carregar a próxima faixa. Confira a conexão e tente novamente.');}syncPlayback();}
function toggle(id){const t=byId(id)||state.current;if(!t)return;if(t.id!==state.current?.id){loadTrack(t);return;}audio.paused?play():audio.pause();}
let plannedNext=null,autoAttempted='';
function nextTrack(direction=1){const options=queue.filter(id=>byId(id));if(!options.length)return null;const position=options.indexOf(state.current?.id),key=state.current?.id+'|'+options.join(',')+'|'+shuffled;if(direction===1&&plannedNext?.key===key)return byId(plannedNext.id);let id;if(shuffled&&options.length>1){const rest=options.filter(id=>id!==state.current?.id);id=rest[Math.floor(Math.random()*rest.length)];}else id=options[(position+direction+options.length)%options.length];if(direction===1)plannedNext={id,key};return byId(id);}
function step(direction=1){const t=nextTrack(direction);if(t)loadTrack(t);}
function checkTransition(){const seconds=audio.settings.crossfade;if(!seconds||audio.paused||audio.loop||audio.transitioning||!state.current||!Number.isFinite(audio.duration)||audio.duration<=0)return;const next=nextTrack();if(!next||next.id===state.current.id)return;const left=(audio.duration-audio.currentTime)/audio.playbackRate;const overlap=Math.min(seconds,audio.duration/audio.playbackRate/2,Number(next.duration)>0?Number(next.duration)/audio.playbackRate/2:seconds);if(left<=overlap+8)audio.prepare(media(next.audio_path));if(left>0&&left<=overlap&&autoAttempted!==state.current.id){autoAttempted=state.current.id;loadTrack(next);}}
function updateProgress(){const duration=Number.isFinite(audio.duration)?audio.duration:Number(state.current?.duration)||0;$('seek').max=duration;$('seek').value=audio.currentTime;$('elapsed').textContent=format(audio.currentTime);$('duration').textContent=format(duration);$('seek').setAttribute('aria-valuetext',`${format(audio.currentTime)} de ${format(duration)}`);}
function favorite(id){favorites.has(id)?favorites.delete(id):favorites.add(id);store('kyroshix-favorites',[...favorites]);drawCatalog();syncPlayback();document.querySelectorAll(`[data-favorite="${id}"]`).forEach(b=>{b.classList.toggle('active',favorites.has(id));b.setAttribute('aria-pressed',String(favorites.has(id)));});toast(favorites.has(id)?'Salva nas favoritas deste navegador.':'Removida das favoritas.');}
function drawQueue(){$('queue-list').innerHTML=queue.filter(id=>byId(id)).map(id=>{const t=byId(id);return `<button class="queue-item ${state.current?.id===id?'active':''}" data-play="${esc(id)}"><span class="mini-cover">${cover(t)}</span><span><strong>${esc(t.title)}</strong><small>${esc(t.artists)}</small></span></button>`;}).join('')||'<p class="subtle">Nenhuma faixa na fila.</p>';}
function closeNav(){document.body.classList.remove('nav-open');$('nav-scrim').hidden=true;$('menu-toggle').setAttribute('aria-expanded','false');$('menu-toggle').setAttribute('aria-label','Abrir navegação');}
function setSearch(open){if(matchMedia('(min-width: 1101px)').matches)open=true;$('site-search').hidden=!open;$('search-toggle').setAttribute('aria-expanded',String(open));document.body.classList.toggle('search-open',open);if(open&&!matchMedia('(min-width: 1101px)').matches)$('search').focus();}

function login(){closeNav();setSearch(false);document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('account-open').click();}
function requireClient(){if(!state.client)throw new Error('A comunidade ainda está sendo ativada. As músicas continuam disponíveis.');return state.client;}
function requireUser(){if(!authState.user){login();return false;}if(!authState.user.emailVerified&&!authState.user.phoneNumber){login();toast('Confirme seu e-mail para usar a comunidade.');return false;}return true;}
function syncAccountAvatar(){
 const user=authState.user,trigger=$('account-open');trigger.classList.toggle('has-account-avatar',!!user);
 if(!user){trigger.textContent='Entrar';trigger.setAttribute('aria-label','Entrar na conta');return;}
 const profile=state.profile||{display_name:user.displayName||'K'},content=avatar(profile,'account-avatar');trigger.innerHTML=content+'<span class="account-label">Minha conta</span>';trigger.setAttribute('aria-label','Abrir minha conta');
 $('profile-initial').innerHTML=content;$('profile-initial').classList.add('account-photo-container');
 if(state.profile?.display_name)$('profile-name').textContent=state.profile.display_name;
}
// A deleted/unavailable image falls back to its owner's initial, never a broken icon.
document.addEventListener('error',e=>{const img=e.target;if(img.tagName!=='IMG'||!img.closest('.avatar,.profile-avatar,.account-avatar,.channel-avatar'))return;const parent=img.parentElement;img.remove();parent.classList.remove('has-image');parent.textContent=parent.dataset.initial||Array.from(parent.closest('.profile-card')?.querySelector('h1,h3')?.textContent||'K')[0];},true);
async function identity(){const epoch=++identityEpoch;state.owner=false;state.profile=null;const user=authState.user;if(state.client&&user){try{const [owner,profile]=await Promise.all([state.client.rpc('is_owner'),state.client.profile(user.uid)]);if(epoch!==identityEpoch)return;state.owner=owner===true;state.profile=profile;}catch{if(epoch!==identityEpoch)return;}}if(epoch!==identityEpoch)return;syncAccountAvatar();document.querySelector('.owner-dot').hidden=!state.owner;if(state.view==='studio')drawStudio();if(state.view==='perfil')drawProfile();drawComposer();drawComments();platform.refresh();}
async function reloadTracks(){const prior=state.current;state.tracks=await requireClient().tracks();queue=state.tracks.map(t=>t.id);if(prior){const updated=byId(prior.id);if(!updated){audio.pause();state.current=null;if(state.tracks[0])loadTrack(state.tracks[0],false);else{$('player-title').textContent='Nenhuma música';$('player-artist').textContent='';audio.removeAttribute('src');setDownload($('player-download'),null);}}else if(updated.audio_path!==prior.audio_path){loadTrack(updated,false);}else{state.current=updated;$('player-title').textContent=updated.title;$('player-artist').textContent=updated.artists;paintCover($('player-cover'),updated);setDownload($('player-download'),updated);}}else if(state.tracks[0])loadTrack(state.tracks[0],false);drawCatalog();drawStudio();syncPlayback();}
function drawDetail(id){const t=byId(id);if(!t){$('track-detail').innerHTML='<div class="empty-state"><h1>Faixa não encontrada</h1><p>Ela pode ter sido removida do catálogo.</p></div>';$('comment-form').hidden=true;$('comments-list').innerHTML='';message('comments-status','');$('comments-more').hidden=true;$('related-tracks').innerHTML='';state.commentTrack=null;return;}
 $('track-detail').innerHTML=`<div class="detail-art">${cover(t)}<button class="detail-play" data-play="${esc(t.id)}" aria-label="Reproduzir ${esc(t.title)}">${icon('play')}</button><img class="cover-mark" src="/assets/wordmark.svg" alt="KYROSHIX RELEASES"></div><h1 class="detail-title">${esc(t.title)}</h1><p class="detail-artists">${esc(t.artists)}</p><div class="detail-actions"><a class="primary" href="${esc(downloadUrl(t))}" download="${esc(downloadName(t))}">${icon('download')}Baixar áudio</a><button class="secondary ${favorites.has(t.id)?'active':''}" data-favorite="${esc(t.id)}" aria-pressed="${favorites.has(t.id)}">${icon('heart')}Favoritar</button><button class="secondary" data-share="${esc(t.id)}">${icon('share')}Compartilhar</button>${state.owner?`<button class="text-button" data-edit-track="${esc(t.id)}">${icon('edit')}Editar</button>`:''}</div><div class="detail-description"><p><strong>${esc(t.remix)}</strong> · ${format(t.duration)} · ${audioExtension(t).toUpperCase()}${t.byte_size?' · '+(t.byte_size/1048576).toFixed(1).replace('.',',')+' MB':''}</p><p>${esc(t.description||'')}</p><details><summary>Créditos da faixa</summary><p>${esc(t.credits||'Remix por KYROSHIX.')}</p></details></div>`;
 $('related-tracks').innerHTML=state.tracks.filter(x=>x.id!==id).slice(0,5).map(x=>`<a class="related-track" href="${esc(trackPath(x))}"><span class="mini-cover">${cover(x)}</span><span><strong>${esc(x.title)}</strong><small>${esc(x.artists)}</small><small>${format(x.duration)} · ${esc(x.remix)}</small></span></a>`).join('');
 platform.track(t);const changed=state.commentTrack!==id;state.commentTrack=id;if(changed){state.comments=[];$('comment-body').value='';resetComment();}drawComposer();loadComments(false);syncPlayback();
}
function drawComposer(){const user=authState.user;$('comment-form').hidden=!state.commentTrack;$('composer-avatar').outerHTML=avatar(state.profile||{display_name:user?.displayName||'K'}).replace('<span ', '<span id="composer-avatar" ');$('comment-help').textContent=!state.client?'Comentários disponíveis após a ativação da comunidade.':!user?'Entre para participar da conversa.':!user.emailVerified?'Confirme seu e-mail para comentar.':`Comentando como ${state.profile?.display_name||user.displayName||'Ouvinte'}`;$('comment-send').textContent=state.editComment?'Salvar edição':user?'Comentar':'Entrar para comentar';}
function resetComment(){state.reply=null;state.editComment=null;$('reply-label').hidden=true;$('comment-cancel').hidden=true;drawComposer();}
function drawComments(){$('comments-list').innerHTML=state.comments.length?state.comments.map(c=>`<article class="comment ${c.deleted?'deleted':''}" id="comment-${esc(c.id)}"><a href="${esc(routePath('perfil',c.user_id))}" aria-label="Ver perfil de ${esc(c.profile?.display_name||'Ouvinte')}">${avatar(c.profile)}</a><div class="comment-content"><div class="comment-meta"><a href="${esc(routePath('perfil',c.user_id))}"><strong>${esc(c.profile?.display_name||'Ouvinte')}</strong></a><small>${new Date(c.created_at).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}${c.edited_at&&!c.deleted?' · editado':''}</small></div>${c.parent_id?'<span class="comment-reply-to">↳ Em resposta a um comentário</span>':''}<p class="comment-body">${c.deleted?'Comentário excluído.':esc(c.body)}</p>${!c.deleted?`<div class="comment-actions"><button data-reply="${esc(c.parent_id||c.id)}">Responder</button>${c.user_id===authState.user?.uid?`<button data-edit-comment="${esc(c.id)}">Editar</button>`:''}${c.user_id===authState.user?.uid||state.owner?`<button data-delete-comment="${esc(c.id)}">Excluir</button>`:''}</div>`:''}</div></article>`).join(''):'<div class="empty-state comment"><h3>Comece a conversa.</h3><p>Conte o que você achou dessa faixa.</p></div>';}
async function loadComments(more=false){const id=state.commentTrack;if(!id)return;const epoch=++commentEpoch;if(!state.client){state.comments=[];$('comments-list').innerHTML='';$('comments-more').hidden=true;message('comments-status','A comunidade ainda está sendo ativada. Volte em breve para comentar.');return;}message('comments-status','Carregando comentários…');$('comments-more').disabled=true;try{const page=await state.client.comments(id,more?state.comments.length:0);if(epoch!==commentEpoch||id!==state.commentTrack)return;state.comments=more?[...state.comments,...page.filter(c=>!state.comments.some(x=>x.id===c.id))]:page;drawComments();message('comments-status');$('comments-more').hidden=page.length<30;}catch(e){if(epoch===commentEpoch)message('comments-status',e.message,'error');}finally{if(epoch===commentEpoch)$('comments-more').disabled=false;}}
function profileCard(profile,own=false,preview=false){const banner=profile._bannerUrl||media(profile.banner_path,profile.updated_at),av=profile._avatarUrl||media(profile.avatar_path,profile.updated_at),name=profile.display_name||'Ouvinte';return `<article class="profile-card" style="--accent:${accent(profile.accent)}"><div class="profile-banner" ${banner?`style="background-image:url('${esc(banner)}')"`:''}></div><div class="profile-card-inner"><div class="profile-avatar ${av?'has-image':''}">${av?`<img src="${esc(av)}" alt="Avatar de ${esc(name)}">`:esc(Array.from(name)[0].toUpperCase())}</div><div class="profile-name-row"><${preview?'h3':'h1'}>${esc(name)}</${preview?'h3':'h1'}>${own&&!preview?'<button class="secondary" data-profile-edit>Editar perfil</button>':''}</div>${profile.pronouns?`<p class="profile-pronouns">${esc(profile.pronouns)}</p>`:''}${own&&state.owner&&!preview?'<span class="owner-badge">Dono do site</span>':''}${profile.status?`<div class="profile-status">${esc(profile.status)}</div>`:''}<div class="profile-bio"><p class="eyebrow">SOBRE MIM</p><p>${esc(profile.bio||'Ainda sem descrição.')}</p></div></div></article>`;}
async function drawProfile(uid){const epoch=routeEpoch;uid=uid||router.current().argument||authState.user?.uid;const own=!!authState.user&&uid===authState.user.uid;$('profile-gate').hidden=!!uid;$('public-profile').innerHTML='';if(!uid)return;try{if(!state.client){$('public-profile').innerHTML='<div class="empty-state"><h1>Seu perfil está chegando.</h1><p>A personalização será liberada quando a comunidade estiver conectada.</p></div>';return;}const p=own?state.profile:await state.client.profile(uid);if(epoch!==routeEpoch||state.view!=='perfil')return;if(!p&&!own){$('public-profile').innerHTML='<div class="empty-state"><h1>Perfil não encontrado</h1><p>Essa pessoa ainda não publicou um perfil.</p></div>';return;}$('public-profile').innerHTML=profileCard(p||{display_name:authState.user?.displayName||'Ouvinte'},own);platform.profile(uid,p);}catch(e){if(epoch===routeEpoch)$('public-profile').innerHTML=`<p class="inline-message">${esc(e.message)}</p>`;}}
function drawStudio(){const allowed=state.owner&&!!state.client;$('add-track').hidden=!allowed;$('studio-content').hidden=!allowed;$('studio-gate').hidden=allowed;$('studio-status').textContent=!state.client?'O estúdio precisa da ativação da comunidade. Depois, somente sua conta de dono terá acesso.':!authState.user?'Entre com a conta do dono para gerenciar músicas.':'Este painel é exclusivo da conta do dono. Se você é o dono, confira o UID autorizado na configuração.';$('studio-gate').querySelector('[data-login]').hidden=!!authState.user;if(!allowed)return;$('studio-count').textContent=state.tracks.length;$('studio-list').innerHTML=state.tracks.map(t=>`<div class="studio-row"><span class="mini-cover">${cover(t)}</span><div class="studio-row-text"><strong>${esc(t.title)} ${t.featured?'<span class="owner-badge">Destaque</span>':''}</strong><small>${esc(t.artists)} · ${format(t.duration)}</small></div><div class="studio-row-actions"><button class="secondary" data-edit-track="${esc(t.id)}" aria-label="Editar ${esc(t.title)}">${icon('edit')}<span>Editar</span></button><button class="text-button" data-delete-track="${esc(t.id)}" aria-label="Excluir ${esc(t.title)}">${icon('trash')}<span>Excluir</span></button></div></div>`).join('')||'<div class="empty-state"><h2>Seu próximo lançamento começa aqui.</h2><p>Use Adicionar música para publicar seu primeiro áudio.</p></div>';platform.studio();}
function route(){
 ++routeEpoch;const {name,argument}=router.current();state.view=name;
 document.body.classList.toggle('home-route',state.view==='inicio'&&!state.query);
 document.querySelectorAll('main>.view').forEach(el=>el.hidden=true);
 document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===state.view);if(a.dataset.nav===state.view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 closeNav();
 if(platform.route(name,name==='assistir'?contentId(argument):argument)){}
 else if(name==='faixa'){const track=resolveTrackKey(argument,state.tracks);if(track)router.canonicalize(trackPath(track));$('view-track').hidden=false;drawDetail(track?.id||argument);}
 else if(name==='perfil'){$('view-profile').hidden=false;drawProfile(argument||undefined);}
 else if(name==='studio'){$('view-studio').hidden=false;drawStudio();}
 else if(name==='not-found'){$('view-not-found').hidden=false;}
 else{$('view-catalog').hidden=false;drawCatalog();}
 window.scrollTo({top:0,behavior:'instant'});
}
function modalBusy(dialog,busy){dialog.dataset.busy=String(busy);dialog.querySelectorAll('input,textarea,select,button').forEach(el=>el.disabled=busy);dialog.setAttribute('aria-busy',String(busy));}
function updateProfilePreview(){if(!profileDraft)return;profileDraft={...profileDraft,display_name:$('edit-name').value,pronouns:$('edit-pronouns').value,status:$('edit-status').value,bio:$('edit-bio').value,accent:$('edit-accent').value};$('profile-preview').innerHTML=profileCard(profileDraft,false,true);}
function openProfileEditor(){try{requireClient();if(!requireUser())return;document.querySelectorAll('dialog[open]').forEach(d=>d.close());profileDraft={display_name:authState.user.displayName||'Ouvinte',bio:'',pronouns:'',status:'',accent:'#353535',avatar_path:'',banner_path:'',...state.profile};profileBlobs={};for(const [id,key]of Object.entries({'edit-name':'display_name','edit-pronouns':'pronouns','edit-status':'status','edit-bio':'bio','edit-accent':'accent'}))$(id).value=profileDraft[key];$('edit-avatar').value='';$('edit-banner').value='';message('profile-save-status');updateProfilePreview();$('profile-editor').showModal();}catch(e){toast(e.message);}}
let pendingProfileImages=0,profileImageEpoch={avatar:0,banner:0};
for(const kind of ['avatar','banner']){
 $(`edit-${kind}`).addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const epoch=++profileImageEpoch[kind];pendingProfileImages++;$('save-profile').disabled=true;try{const blob=await prepareImage(file,kind==='avatar'?1024:2560,kind==='avatar'?1024:960);if(epoch!==profileImageEpoch[kind])return;profileBlobs[kind]=blob;if(profileDraft['_'+kind+'Url'])URL.revokeObjectURL(profileDraft['_'+kind+'Url']);profileDraft['_'+kind+'Url']=URL.createObjectURL(blob);updateProfilePreview();message('profile-save-status');}catch(error){message('profile-save-status',error.message,'error');}finally{pendingProfileImages--;if(!pendingProfileImages)$('save-profile').disabled=false;}});
 $(`remove-${kind}`).addEventListener('click',()=>{profileImageEpoch[kind]++;profileBlobs[kind]=null;profileDraft[kind+'_path']='';if(profileDraft['_'+kind+'Url'])URL.revokeObjectURL(profileDraft['_'+kind+'Url']);delete profileDraft['_'+kind+'Url'];$(`edit-${kind}`).value='';updateProfilePreview();});
}
$('profile-form').addEventListener('input',updateProfilePreview);
$('profile-form').addEventListener('submit',async e=>{e.preventDefault();if(profileBusy||pendingProfileImages||!$('profile-form').reportValidity()||!requireUser())return;profileBusy=true;modalBusy($('profile-editor'),true);message('profile-save-status','Salvando seu perfil…');const uid=authState.user.uid;try{const client=requireClient();for(const kind of ['avatar','banner']){if(profileBlobs[kind]){const path=`profiles/${uid}/${kind}.webp`;await client.upload(path,profileBlobs[kind],p=>message('profile-save-status',`Enviando ${kind==='avatar'?'foto de perfil':'banner'}… ${p}%`));profileDraft[kind+'_path']=path;}}message('profile-save-status','Salvando seu perfil…');const {display_name,bio,pronouns,status,accent:color,avatar_path,banner_path}=profileDraft;const result=await client.rpc('save_profile',{p_profile:{display_name:display_name.trim(),bio,pronouns,status,accent:color,avatar_path,banner_path}});if(authState.user?.uid===uid){state.profile=result;syncAccountAvatar();}$('profile-editor').close();toast('Perfil publicado.');drawComposer();if(state.view==='perfil')drawProfile();}catch(error){message('profile-save-status',error.message,'error');}finally{profileBusy=false;modalBusy($('profile-editor'),false);}});
$('profile-editor').addEventListener('close',()=>{for(const kind of ['avatar','banner']){profileImageEpoch[kind]++;if(profileDraft?.['_'+kind+'Url'])URL.revokeObjectURL(profileDraft['_'+kind+'Url']);}});
function openTrackEditor(id){if(!state.owner){toast('O estúdio é exclusivo da conta do dono.');return;}trackDraft=id?{...byId(id)}:{id:crypto.randomUUID(),title:'',artists:'',remix:'Nightcore Remix',tags:['nightcore'],description:'',credits:'',duration:0,featured:false,cover_path:'',audio_path:'',legacy_cover:'',byte_size:0};trackBlob=null;if(editImageUrl){URL.revokeObjectURL(editImageUrl);editImageUrl='';}$('track-form').reset();$('edit-track-id').value=trackDraft.id;$('track-editor-title').textContent=id?'Editar música':'Adicionar música';$('save-track').textContent=id?'Salvar alterações':'Publicar música';for(const [field,key]of Object.entries({'edit-title':'title','edit-artists':'artists','edit-remix':'remix','edit-description':'description','edit-credits':'credits'}))$(field).value=trackDraft[key]||'';$('edit-tags').value=trackDraft.tags.join(',');if(!$('edit-tags').value)$('edit-tags').value='remix';$('edit-featured').checked=trackDraft.featured;$('edit-cover-preview').innerHTML=id?cover(trackDraft):`${icon('disc')}<span>Sua próxima capa</span>`;$('audio-file-hint').textContent=id?`Áudio atual: ${format(trackDraft.duration)} · ${(trackDraft.byte_size/1048576).toFixed(1)} MB`:'MP3, FLAC, WAV, M4A ou OGG. Até 50 MB por faixa.';message('track-save-status');$('upload-progress').hidden=true;$('track-editor').showModal();}
let trackImagePending=false,trackImageEpoch=0;
$('edit-cover-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const epoch=++trackImageEpoch;trackImagePending=true;$('save-track').disabled=true;try{const blob=await prepareImage(file,2400,2400);if(epoch!==trackImageEpoch)return;trackBlob=blob;if(editImageUrl)URL.revokeObjectURL(editImageUrl);editImageUrl=URL.createObjectURL(blob);$('edit-cover-preview').innerHTML=`<img src="${esc(editImageUrl)}" alt="Prévia da capa" style="width:100%;height:100%;object-fit:cover">`;message('track-save-status');}catch(error){message('track-save-status',error.message,'error');}finally{if(epoch===trackImageEpoch){trackImagePending=false;$('save-track').disabled=false;}}});
$('track-editor').addEventListener('close',()=>{trackImageEpoch++;trackImagePending=false;if(editImageUrl)URL.revokeObjectURL(editImageUrl);editImageUrl='';});
$('track-form').addEventListener('submit',async e=>{e.preventDefault();if(trackBusy||trackImagePending||!state.owner||!$('track-form').reportValidity())return;const file=$('edit-audio-file').files[0];if(!file&&!trackDraft.audio_path){message('track-save-status','Escolha um arquivo de áudio para publicar.','error');return;}trackBusy=true;modalBusy($('track-editor'),true);message('track-save-status','Preparando sua música…');const uploaded=[];let committed=false;try{const client=requireClient();const next={...trackDraft,title:$('edit-title').value.trim(),artists:$('edit-artists').value.trim(),remix:$('edit-remix').value.trim(),description:$('edit-description').value,credits:$('edit-credits').value,tags:$('edit-tags').value.split(','),featured:$('edit-featured').checked};if(!next.title||!next.artists)throw new Error('Preencha o título e os artistas.');const progress=p=>{$('upload-progress').hidden=false;$('upload-progress').value=p;};if(file){next.duration=await inspectAudio(file);next.byte_size=file.size;next.audio_path=`tracks/${next.id}/${crypto.randomUUID()}.${audioExtension(file)}`;message('track-save-status','Enviando áudio original… Mantenha esta página aberta.');await client.upload(next.audio_path,new Blob([file],{type:audioTypes[audioExtension(file)]}),progress);uploaded.push(next.audio_path);}if(trackBlob){next.cover_path=`tracks/${next.id}/${crypto.randomUUID()}.webp`;message('track-save-status','Enviando capa…');await client.upload(next.cover_path,trackBlob,progress);uploaded.push(next.cover_path);}message('track-save-status','Publicando no catálogo…');const result=await client.rpc('save_track',{p_track:next});committed=true;const oldPaths=[trackDraft.audio_path,trackDraft.cover_path].filter(path=>path&&path!==result.audio_path&&path!==result.cover_path&&!state.tracks.some(t=>t.id!==result.id&&(t.audio_path===path||t.cover_path===path)));$('track-editor').close();toast('Música publicada.');try{await reloadTracks();}catch{toast('Música salva. Recarregue a página para atualizar o catálogo.');}if(oldPaths.length)client.removeFiles(oldPaths).catch(()=>toast('Música salva. Um arquivo antigo ainda precisa ser removido do armazenamento.'));if(state.view==='faixa')drawDetail(result.id);}catch(error){message('track-save-status',error.message,'error');if(!committed&&uploaded.length)await state.client.removeFiles(uploaded).catch(()=>message('track-save-status',error.message+' Há arquivos enviados que podem ser removidos no armazenamento.','error'));}finally{trackBusy=false;modalBusy($('track-editor'),false);$('upload-progress').hidden=true;}});
let confirmationResolve=null;
function confirmAction(title,text){$('confirm-title').textContent=title;$('confirm-text').textContent=text;$('confirm-dialog').showModal();return new Promise(resolve=>{confirmationResolve=resolve;});}
$('confirm-yes').addEventListener('click',()=>{confirmationResolve?.(true);confirmationResolve=null;$('confirm-dialog').close();});$('confirm-cancel').addEventListener('click',()=>{$('confirm-dialog').close();});$('confirm-dialog').addEventListener('close',()=>{confirmationResolve?.(false);confirmationResolve=null;});
async function deleteTrack(id){const t=byId(id);if(!t||!state.owner)return;if(!await confirmAction('Excluir música?',`“${t.title}” será removida do catálogo, junto com seus comentários. Essa ação não pode ser desfeita.`))return;try{await requireClient().rpc('delete_track',{p_id:id});const paths=[t.audio_path,t.cover_path].filter(path=>path&&!state.tracks.some(x=>x.id!==id&&(x.audio_path===path||x.cover_path===path)));await reloadTracks();toast('Música excluída.');if(paths.length)state.client.removeFiles(paths).catch(()=>toast('Música excluída do catálogo. Os arquivos restantes podem ser removidos no armazenamento.'));}catch(e){toast(e.message);}}
$('comment-form').addEventListener('submit',async e=>{e.preventDefault();if(commentBusy)return;try{const client=requireClient();if(!requireUser())return;const body=$('comment-body').value.trim();if(!body)return;const id=state.commentTrack;commentBusy=true;$('comment-send').disabled=true;message('comments-status','Publicando…');if(!state.profile)state.profile=await client.rpc('save_profile',{p_profile:{display_name:authState.user.displayName||'Ouvinte'}});if(state.editComment)await client.rpc('edit_comment',{p_id:state.editComment,p_body:body});else await client.rpc('comment',{p_track:id,p_body:body,p_parent:state.reply});if(id===state.commentTrack){$('comment-body').value='';resetComment();await loadComments();}}catch(error){message('comments-status',error.message,'error');}finally{commentBusy=false;$('comment-send').disabled=false;}});
$('comment-cancel').addEventListener('click',()=>{$('comment-body').value='';resetComment();});$('comments-refresh').addEventListener('click',()=>loadComments());$('comments-more').addEventListener('click',()=>loadComments(true));
$('comments-list').addEventListener('click',async e=>{const reply=e.target.closest('[data-reply]'),edit=e.target.closest('[data-edit-comment]'),remove=e.target.closest('[data-delete-comment]');if(reply){if(!requireUser())return;state.reply=reply.dataset.reply;state.editComment=null;$('reply-label').textContent='Respondendo ao comentário';$('reply-label').hidden=false;$('comment-cancel').hidden=false;drawComposer();$('comment-body').focus();}if(edit){const c=state.comments.find(x=>x.id===edit.dataset.editComment);if(!c)return;state.editComment=c.id;state.reply=null;$('comment-body').value=c.body;$('reply-label').textContent='Editando seu comentário';$('reply-label').hidden=false;$('comment-cancel').hidden=false;drawComposer();$('comment-body').focus();}if(remove){if(!await confirmAction('Excluir comentário?','O texto será removido. As respostas continuam na conversa.'))return;try{await requireClient().rpc('delete_comment',{p_id:remove.dataset.deleteComment});await loadComments();}catch(error){message('comments-status',error.message,'error');}}});
